SELECT product_id
FROM Products
WHERE low_fats = 'Y' AND recyclable = 'Y';

SELECT name
FROM Customer
WHERE referee <> 2 OR referee IS NULL;

SELECT name, population, area
FROM World
WHERE area >= 3000000 OR population >= 25000000;

SELECT tweet_id
FROM Tweets
WHERE LEN(content) > 15;

SELECT u.unique_id, e.name
FROM Employees e
JOIN EmployeeUNI u ON e.id = u.employee_id;

SELECT p.product_name, s.year, s.price
FROM Sales s
JOIN Product p ON s.product_id = p.product_id;

SELECT transaction_id
FROM (
  SELECT transaction_id,
    DENSE_RANK() OVER (
      PARTITION BY DAY(day) ORDER BY amount DESC
    ) AS dr
  FROM Transactions
) x
WHERE dr = 1;

SELECT MAX(salary) AS SecondHighestSalary
FROM Employee
WHERE salary < (SELECT MAX(salary) FROM Employee);

SELECT score,
  RANK() OVER (ORDER BY score DESC) AS rank
FROM Scores;

SELECT d.name AS Department, e.name AS Employee, e.salary
FROM (
  SELECT *, DENSE_RANK() OVER (
    PARTITION BY departmentId ORDER BY salary DESC
  ) AS dr
  FROM Employee
) e
JOIN Department d ON e.departmentId = d.id
WHERE e.dr <= 3;

SELECT player_id, MIN(event_date) AS first_login
FROM Activity
GROUP BY player_id;

WITH first AS (
  SELECT player_id, MIN(event_date) AS first_login
  FROM Activity GROUP BY player_id
)
SELECT ROUND(
  1.0 * SUM(CASE WHEN DATEDIFF(day, f.first_login, a.event_date) = 1 THEN 1 ELSE 0 END)
  / COUNT(DISTINCT f.player_id), 2
) AS fraction
FROM first f
LEFT JOIN Activity a ON f.player_id = a.player_id;

SELECT x, y, z
FROM Triangle
WHERE x + y > z AND x + z > y AND y + z > x;

SELECT DISTINCT f1.follower
FROM Follow f1
JOIN Follow f2 ON f1.followee = f2.follower;

SELECT student_id, course_id, grade
FROM (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY student_id ORDER BY grade DESC, course_id
  ) AS rn
  FROM Enrollments
) x
WHERE rn = 1;

SELECT product_id, new_price AS price
FROM (
  SELECT product_id, new_price,
    ROW_NUMBER() OVER (
      PARTITION BY product_id ORDER BY change_date DESC
    ) AS rn
  FROM Products
  WHERE change_date <= '2019-08-16'
) x
WHERE rn = 1;
